<script setup>
import {computed,ref,watch} from 'vue';
import {dailyReadiness as state,dailyReadinessError as error,dailyReadinessBusy as busy,changeDailyReadiness,refreshDailyReadiness} from './daily-readiness-store.mjs';
import {dailyBuildGroups,dailyEntries,dailyScopeLabel} from './daily-readiness.mjs';
import {myWorkSnapshot,pullMyWork} from './my-work-store.mjs';
import {activeTab,setActivePanelTab} from './store.js';
import {openTestPackage} from './test-packages-store.mjs';
import ReadinessProgress from './ReadinessProgress.vue';
import ReadinessWorkflow from './ReadinessWorkflow.vue';
import IssueReadiness from './IssueReadiness.vue';
const props=defineProps({scopeConfig:Object});
const scanBusy=ref(false);
async function scan(){scanBusy.value=true;try{if(props.scopeConfig)await pullMyWork(props.scopeConfig);await changeDailyReadiness('scan');}catch(e){error.value=e.message;}finally{scanBusy.value=false;}}
const filter=ref('all'),limit=ref(20);
const report=computed(()=>state.value.report),running=computed(()=>report.value?.status==='running');
const builds=computed(()=>dailyBuildGroups(report.value?.entries));
const entries=computed(()=>dailyEntries(report.value?.entries,filter.value));
const greenCount=computed(()=>dailyEntries(report.value?.entries,'green').length);
const differentScope=computed(()=>report.value&&myWorkSnapshot.value&&['repo','milestone','scope','user','label'].some(key=>report.value.config[key]!==myWorkSnapshot.value.config[key]));
const changedIssues=computed(()=>{if(!report.value||!myWorkSnapshot.value||differentScope.value||running.value)return false;const current=new Set(myWorkSnapshot.value.issues.filter(issue=>issue.state!=='closed'&&!(issue.labels||[]).some(label=>label.name.toLowerCase()==='qa/none')).map(issue=>issue.html_url.toLowerCase()));return report.value.entries.some(entry=>!entry.closed&&!entry.qaNone&&!current.has(entry.issueUrl.toLowerCase()));});
const qaLabel=entry=>({found:'QA template found on GitHub',draft:'QA template found on GitHub · needs details',not_found:'No QA template found on GitHub',not_required:'QA not required · QA/None',unknown:entry.verdict==='pending'?'Not scanned yet':'QA template check incomplete'}[entry.qaState]||'QA template check incomplete');
const safeLink=url=>{try{const value=new URL(url);return value.protocol==='https:'&&value.hostname==='github.com'&&!value.username&&!value.password;}catch{return false;}};
watch(filter,()=>{limit.value=20;});
watch(activeTab,tab=>{if(tab==='my-work')void refreshDailyReadiness();});
</script>
<template>
 <section class="daily-panel" aria-label="Readiness briefing">
  <header><div><span class="daily-eyebrow">Issue readiness</span><h2>Readiness briefing</h2><p>Build evidence, QA guidance, and plans to prepare.</p></div><div class="daily-actions"><button :disabled="busy||scanBusy||running||!myWorkSnapshot" @click="scan">{{running?'Scanning…':'Scan now'}}</button><button v-if="running" :disabled="busy" @click="changeDailyReadiness('cancel')">Cancel scan</button><button class="daily-subtle" @click="setActivePanelTab('settings')">Daily scan {{state.enabled?'on':'off'}} · Settings ↗</button></div></header>
  <p v-if="error||state.storageError" class="daily-alert" role="alert">{{error||state.storageError}}</p>
  <template v-if="report">
   <div class="daily-meta"><strong>{{report.milestone}}</strong><span>{{dailyScopeLabel(report.config)}}</span><span>{{new Date(report.startedAt).toLocaleString()}} · {{report.status}}</span></div>
   <p v-if="differentScope" class="daily-alert">This saved report is for a different My Work scope. Scan now to check the current scope.</p>
   <p v-if="changedIssues" class="daily-alert">Your GitHub issue list has changed since this saved report. Scan now to update its counts and build observations.</p>
   <ReadinessProgress v-if="running" :progress="report.progress||[]" :started-at="report.startedAt"/><p v-if="running&&report.currentIssue" class="daily-caption">Checking: {{report.currentIssue}}</p><div v-if="running" role="status" class="daily-progress"><span>{{report.total?`${report.checked} of ${report.total} issues checked`:'Refreshing your milestone from GitHub…'}}</span><progress :value="report.checked" :max="report.total||1"></progress></div>
   <p v-if="report.error" class="daily-alert">{{report.error}}</p>
   <div class="daily-stats">
    <button :aria-pressed="filter==='ready'" @click="filter='ready'"><strong>{{report.ready}}</strong><span>Fixes in a Rancher build</span></button>
    <button :aria-pressed="filter==='plans'" @click="filter='plans'"><strong>{{report.needsPlan}}</strong><span>Need saved test cases</span></button>
    <div><strong>{{report.qaFound}}</strong><span>QA template found on GitHub</span></div>
    <button :aria-pressed="filter==='qa'" @click="filter='qa'"><strong>{{report.qaMissing}}</strong><span>Missing QA template / details</span></button>
   </div>
   <p class="daily-caption">{{greenCount}} green {{greenCount===1?'light':'lights'}} to test · {{report.checked}} checked · {{report.remaining}} unchecked · {{report.incomplete}} incomplete checks · {{report.qaUnknown}} QA checks unresolved. Saved observations, including local test-case coverage, are from this scan.</p>
   <div v-if="builds.length" class="daily-builds"><h3>Available in these head builds</h3><article v-for="build in builds" :key="build.reference+build.serverDigest"><div><strong>{{build.count}} {{build.count===1?'issue':'issues'}}</strong><span>{{build.label}}</span></div><code>{{build.reference}}</code><details><summary>Observed server &amp; agent digests</summary><code>{{build.serverDigest}}</code><code>{{build.agentReference}}</code><code>{{build.agentDigest}}</code></details></article><p class="daily-caption">Each issue has all required fixes in that build. A green light also requires To Test or QA Working status. An issue can appear in more than one build.</p></div>
   <div class="daily-list-heading"><h3>Issue observations</h3><select v-model="filter" aria-label="Filter daily report"><option value="all">All observations</option><option value="ready">Fixes in a build</option><option value="green">Green light to test</option><option value="plans">Need test cases</option><option value="qa">Need QA guidance</option><option value="unchecked">Unchecked</option></select></div>
   <ol class="daily-list"><li v-for="entry in entries.slice(0,limit)" :key="entry.issueUrl"><div class="daily-issue"><a v-if="safeLink(entry.issueUrl)" :href="entry.issueUrl" target="_blank" rel="noopener noreferrer">#{{entry.number}} · {{entry.title}}</a><span :data-ready="!!entry.workflow?.greenLight&&!entry.closed&&!entry.qaNone">{{entry.qaNone?'QA not required':entry.closed?'Closed on GitHub':entry.workflow?.greenLight?'Green light to test':entry.verdict==='ready'?'Build available · confirm workflow':entry.verdict.replaceAll('_',' ')}}</span></div><details class="daily-evidence"><summary>Workflow &amp; evidence</summary><p>{{entry.error||entry.detail}}</p><ReadinessWorkflow v-if="entry.verdict!=='pending'" :workflow="entry.workflow" :statuses="entry.statuses" :build-available="entry.verdict==='ready'" compact/><div class="daily-tags" :data-qa-missing="entry.qaComplete&&['not_found','draft'].includes(entry.qaState)"><a v-if="safeLink(entry.qaUrl)" :href="entry.qaUrl" target="_blank" rel="noopener noreferrer">{{qaLabel(entry)}} ↗</a><span v-else>{{qaLabel(entry)}}</span><span v-if="!entry.closed&&!entry.qaNone">{{entry.needsPlan?'Needs saved test cases':'Test cases saved in Runway'}}</span></div></details><div class="daily-row-actions"><button v-if="entry.packageId" @click="openTestPackage(entry.packageId)">Open test package ↗</button><IssueReadiness :issue-url="entry.issueUrl" compact/></div></li></ol>
   <p v-if="!entries.length" class="daily-caption">{{report.total?'No issues match this view.':running?'Issue observations will appear as the scan progresses.':report.status==='completed'?'No open issues in this scope.':'No issue observations were saved.'}}</p>
   <button v-if="entries.length>limit" @click="limit+=20">Show more ({{entries.length-limit}} remaining)</button>
  </template>
  <p v-else class="daily-empty">{{myWorkSnapshot?'Scan your saved milestone now, or enable daily scanning in Settings. Your report stays here between app launches.':'Pull a milestone below to prepare packages and choose the scope for your daily report.'}}</p>
 </section>
</template>
<style scoped>
.daily-panel{border:1px solid var(--runway-border,#dfe7e4);border-radius:20px;padding:24px;background:var(--runway-card,#fff);color:var(--runway-ink,#203230)}header,.daily-actions,.daily-meta,.daily-list-heading,.daily-issue,.daily-row-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.daily-actions{justify-content:flex-end}.daily-eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.13em;color:var(--runway-accent,#16735e)}h2{font-size:28px;font-weight:650;letter-spacing:-.04em;margin:6px 0}header p,.daily-caption,.daily-empty,.daily-meta{color:var(--runway-muted,#657577);font-size:12px;line-height:1.7}.daily-panel button,select{border:1px solid var(--runway-border,#dfe7e4);border-radius:8px;background:var(--runway-raised,#fff);color:inherit;padding:8px 12px;font-size:12px}.daily-panel button{cursor:pointer}.daily-panel button:disabled{opacity:.5;cursor:default}.daily-panel :focus-visible{outline:2px solid #319476;outline-offset:3px}.daily-actions>button:first-child{background:#16735e;color:#fff;border-color:#16735e}.daily-meta{justify-content:flex-start;margin:20px 0 12px}.daily-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0 12px}.daily-stats>button,.daily-stats>div{text-align:left;padding:18px;border-radius:13px;border:1px solid var(--runway-border,#dfe7e4);background:#31947608;display:flex;flex-direction:column;gap:8px}.daily-stats strong{font-size:32px;font-weight:650;letter-spacing:-.04em}.daily-stats span{font-size:11px;color:var(--runway-muted,#657577)}.daily-stats [aria-pressed=true]{border-color:#319476}.daily-progress{display:grid;gap:10px;font-size:12px;padding:12px 0}.daily-progress progress{width:100%;height:6px;accent-color:#319476}.daily-alert{padding:12px 14px;background:#c08a2018;border-radius:10px;font-size:12px;margin:12px 0;overflow-wrap:anywhere}.daily-builds{margin:24px 0;padding:18px;border:1px solid #31947650;border-radius:14px;background:#31947608}.daily-builds article{padding:12px 0;border-bottom:1px solid var(--runway-border,#dfe7e4)}.daily-builds article>div{display:flex;gap:14px;font-size:12px;margin-bottom:5px}.daily-builds code{display:block;font-size:11px;overflow-wrap:anywhere}.daily-builds details{font-size:11px;margin-top:6px;color:var(--runway-muted,#657577)}.daily-builds .daily-caption{margin-top:12px}h3{font-size:14px;font-weight:650}.daily-list-heading{margin-top:22px}.daily-list{list-style:none;margin-top:8px}.daily-list li{padding:18px 0;border-bottom:1px solid var(--runway-border,#dfe7e4)}.daily-issue a{font-size:14px;font-weight:600}.daily-issue>span{font-size:10px;border-radius:5px;padding:4px 8px;background:#c08a2018}.daily-issue>span[data-ready=true]{background:#31947620;color:var(--runway-accent,#16735e)}.daily-list li>p{font-size:12px;margin:8px 0;color:var(--runway-muted,#657577)}.daily-tags{display:flex;flex-wrap:wrap;gap:8px;font-size:10px;color:var(--runway-muted,#657577)}.daily-tags>*{padding:4px 7px;border-radius:5px;background:#3194760b}.daily-tags[data-qa-missing=true]>:first-child{background:#c08a2025;border:1px solid #c08a2070;font-weight:650}.daily-tags a{color:var(--runway-accent,#16735e);text-decoration:underline}.daily-row-actions{justify-content:flex-start;margin-top:12px}.daily-empty{padding:28px 0 8px}@media(max-width:700px){.daily-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.daily-panel{padding:18px}}

.daily-panel{border-radius:10px;padding:16px}h2{font-size:21px}.daily-stats{gap:8px;margin:12px 0}.daily-stats>button,.daily-stats>div{padding:10px 12px;flex-direction:row;align-items:center;gap:10px;border-radius:7px}.daily-stats strong{font-size:22px}.daily-builds{padding:12px;margin:16px 0;border-radius:8px}.daily-list li{padding:12px 0}.daily-issue a{font-size:13px;flex:1}.daily-evidence{font-size:11px;margin-top:7px;color:var(--runway-muted)}.daily-evidence>summary{cursor:pointer}.daily-evidence>p{margin:8px 0}.daily-row-actions{margin-top:8px}
</style>
